let archiveKey=localStorage.getItem('sgs-archive-key');if(!/^[a-f0-9]{64}$/.test(archiveKey||'')){archiveKey=Array.from(crypto.getRandomValues(new Uint8Array(32)),v=>v.toString(16).padStart(2,'0')).join('');localStorage.setItem('sgs-archive-key',archiveKey);}
