 return `<section class="area-chooser simple-area" aria-label="Choose a card from ${esc(target.name)}"><p class="selection-owner">${esc(target.name)}’s cards · ${q.context.action==='steal'?'Choose one to take':q.context.action==='dismantle'?'Choose one to discard':'Choose one card'}</p><div class="area-card-row">${hidden.map((o,i)=>`<button class="area-hidden-card" data-area-option="${o.id}" aria-label="Choose hidden hand card ${i+1} from ${esc(target.name)}"><span>?</span><small>Hand</small></button>`).join('')}${publicCards.map(c=>`<button class="area-public-card ${c.red?'red':''}" data-area-option="${c.id}" data-preview-card="${esc(c.id)}" title="${esc(c.text)}"><span>${c.suit} ${rank(c.rank)}</span><strong>${esc(c.name)}</strong><small>${types[c.type]}</small></button>`).join('')}</div></section>`;
