 return `<div class="inline-use-choices ${bluff?'bluff-choices':''}" aria-label="${bluff?'Choose the card to declare':'Choose card use'}">${bluff?'<span>Declare as</span>':''}${opts.map(o=>{const match=o.label.match(/Claim (.*?) with /);const label=o.id.startsWith('recast:')?'Recast':match?match[1]:o.label;return `<button data-use-option="${esc(o.id)}" data-anchor="${esc(id)}" title="${esc(o.description||label)}">${esc(label)}</button>`;}).join('')}<button data-action="local-cancel">Cancel</button></div>`;
