 return `<div class="self-skills">${buttons.map(o=>`<button ${o.enabled?`data-use-option="${o.id}"`:'disabled'} title="${esc(o.enabled?o.description:g.availability?.skills[o.label]||'Not available now')}">${esc(o.label)}</button>`).join('')}</div>`;
