  if(face.closest('.rail-item'))continue;
  if(!face.querySelector('.card-illustration,.card-emblem')){const c=visiblePreviewCard(face.dataset.previewCard);if(c)(face.querySelector('strong')||face.querySelector('h2')||face.querySelector('span')||face).insertAdjacentHTML('afterend',cardArt(c));}
