if(token){app.innerHTML=header()+'<div class="loading">Reconnecting to your table…</div>';try{state=await api('state');render();stream();}catch{signout();}}else render();

function botStrategySelect(p){return `<label>Strategy <select data-bot-strategy="${esc(p.id)}" aria-label="AI strategy for ${esc(p.name)}" ${p.botMode==='llm'?'':'disabled'}><option value="current" ${(p.botStrategy||'current')==='current'?'selected':''}>Current</option><option value="role-focus" ${p.botStrategy==='role-focus'?'selected':''}>Role-focused</option></select></label>`;}
function botModeSelect(p,r){const configured=r.llm?.models||[],entries=[{id:'classic',label:'Practice bot',enabled:true},...['kimi','claude','deepseek'].map(id=>configured.find(m=>m.id===id)||{id,label:{kimi:'Kimi',claude:'Claude',deepseek:'DeepSeek'}[id],enabled:false}),...configured.filter(m=>m.enabled&&!['kimi','claude','deepseek'].includes(m.id))];const selected=p.botMode==='llm'?p.botModel||configured.find(m=>m.enabled)?.id:'classic';return `<select data-bot-mode="${esc(p.id)}" aria-label="Bot model for ${esc(p.name)}">${entries.map(m=>`<option value="${esc(m.id)}" ${selected===m.id?'selected':''} ${m.enabled?'':'disabled'}>${esc(m.label)}${m.enabled?'':' · Not configured'}</option>`).join('')}</select>${botStrategySelect(p)}`;}

const llmDialog=document.createElement('dialog');llmDialog.id='llm-dialog';document.body.append(llmDialog);
function traceTone(t){return ['model','chat-model','chat-silent','analysis-model'].includes(t.status)?'success':['request-timeout','decision-expired','window-closed','model-switched','match-ended','cancelled','stale'].includes(t.status)?'warning':'error';}
function traceView(t){let system='',input=t.request||'Request not sent',output=t.response||'No model output';try{const r=JSON.parse(t.request);system=(r.system||r.messages?.filter(m=>m.role==='system')||[]).map(m=>m.text||m.content||'').join('\n');const user=r.messages?.find(m=>m.role==='user');const raw=typeof user?.content==='string'?user.content:user?.content?.filter(b=>b.text).map(b=>b.text).join('\n');input=JSON.stringify(JSON.parse(raw),null,2);}catch{}try{output=JSON.stringify(JSON.parse(output),null,2);}catch{}return `<p>${esc(t.validationReason||'')}${t.stopReason?' · Stop: '+esc(t.stopReason):''}${t.usage?' · Tokens: '+esc(t.usage.prompt_tokens||0)+' in / '+esc(t.usage.completion_tokens||0)+' out':''}${t.normalization?' · '+esc(t.normalization):''}</p>${t.acceptedPlan?`<h4>Turn ${t.acceptedPlan.turn} plan · ${esc(t.acceptedPlan.source)} · ${esc(t.acceptedPlan.status)}</h4><p><strong>${esc(t.acceptedPlan.objective)}</strong></p><pre>${esc(JSON.stringify(t.acceptedPlan,null,2))}</pre>`:''}<h4>System prompt</h4><pre class="trace-system">${esc(system||'Not available')}</pre><h4>Input</h4><pre class="trace-input">${esc(input)}</pre><h4>Raw model output</h4><pre class="trace-output">${esc(output)}</pre>`;}
async function showAIControls(){const status=await api('llm-status',{}),r=state.room;llmDialog.innerHTML=`<button data-close-ai aria-label="Close AI controls">×</button><h2>AI controls</h2><label>Bot conversation <select data-bot-chatter>${['off','occasional','lively'].map(m=>`<option value="${m}" ${(r.botChatter||'occasional')===m?'selected':''}>${m[0].toUpperCase()+m.slice(1)}</option>`).join('')}</select></label><p>Bots may react after resolved plays, including their own good moves. Silence is allowed; direct replies still work when Off.</p><p>Select a model and strategy for each bot. Role-focused adds the tested role-objective guidance without extra thinking calls. Unconfigured models are disabled.</p><section><strong>Test AI connection</strong><p>Sends one small request per click. Uses no game data.</p>${(status.models||[]).map(m=>`<button data-test-ai="${esc(m.id)}" ${m.enabled?'':'disabled'}>Test ${esc(m.label)}</button>`).join(' ')}<div class="ai-connection-result" role="status" aria-live="polite"></div></section>${r.players.filter(p=>p.bot).map(p=>{const s=status.seats?.[state.game?.matchId+':'+p.id];return `<section><strong>${esc(p.name)}</strong>${botModeSelect(p,r)}<small>${s?`${s.successes} model decisions · ${s.fallbacks} fallbacks · ${s.chatSuccesses||0} chat replies · Last: ${esc(s.lastStatus)} (${s.lastMs} ms) · Tokens: ${s.inputTokens} in / ${s.outputTokens} out`:'No model requests yet.'}</small></section>`;}).join('')}<button data-refresh-ai>Refresh status</button>${status.debug?`<details class="llm-traces"><summary>Decision inspector · Contains bots’ private hands and identities</summary><p class="trace-legend"><span class="trace-success">● Success</span> · <span class="trace-warning">● Timeout / cancellation</span> · <span class="trace-error">● Invalid response / provider error</span></p>${[...(status.traces||[])].reverse().map(t=>`<details class="trace-entry trace-${traceTone(t)}"><summary>${esc(state.room.players.find(p=>p.id===t.playerId)?.name||t.playerId)} · ${esc(t.model)} · ${esc(t.decisionType)} · ${esc(t.status)} · ${t.elapsedMs} ms</summary>${traceView(t)}</details>`).join('')||'<p>No captured decisions yet.</p>'}</details>`:'<p>Decision inspector is off. Set LLM_DEBUG=1 on the server to inspect prompts, inputs and outputs in testing games.</p>'}<p>Switch to Practice bot to cancel a pending model request and use the tactical fallback. The inspector and saved logs contain private game information.</p>`;if(!llmDialog.open)llmDialog.showModal();}
llmDialog.addEventListener('click',async e=>{const test=e.target.closest('[data-test-ai]');if(test){const result=llmDialog.querySelector('.ai-connection-result');const buttons=[...llmDialog.querySelectorAll('[data-test-ai]:not(:disabled)')];buttons.forEach(b=>b.disabled=true);result.textContent='Testing '+test.textContent.replace('Test ','')+'…';try{const r=await api('llm-check',{model:test.dataset.testAi});result.textContent=(r.ok?'Connected':'Failed · '+r.status)+' · '+r.model+' · '+r.latencyMs+' ms · '+r.inputTokens+' input / '+r.outputTokens+' output tokens';}catch(err){result.textContent=err.message;}finally{buttons.forEach(b=>b.disabled=false);}return;}if(e.target===llmDialog||e.target.closest('[data-close-ai]'))llmDialog.close();if(e.target.closest('[data-refresh-ai]'))try{await showAIControls();}catch(err){toast(err.message);}});
llmDialog.addEventListener('change',async e=>{if(e.target.dataset.botStrategy!==undefined){try{await api('bot-mode',{id:e.target.dataset.botStrategy,strategy:e.target.value});await showAIControls();}catch(err){toast(err.message);}return;}if(e.target.matches('[data-bot-chatter]')){try{await api('bot-chatter',{mode:e.target.value});}catch(err){toast(err.message);}return;}const id=e.target.dataset.botMode;if(!id)return;try{await api('bot-mode',{id,model:e.target.value});await showAIControls();}catch(err){toast(err.message);}});

async function showMatchLogs(){const result=await api('match-logs',{});llmDialog.innerHTML='<button data-close-ai aria-label="Close">×</button><h2>Saved match logs</h2><p>Private archive: game events, chat and AI inputs/outputs, including bot hands and identities.</p>'+result.logs.map(l=>`<p>${esc(new Date(l.startedAt).toLocaleString())} · ${Math.ceil(l.bytes/1024)} KB <button data-review-match="${esc(l.id)}">Review match</button> <button data-download-match="${esc(l.id)}">Download JSONL</button>${l.error?esc(l.error):''}</p>`).join('')+(result.logs.length?'':'<p>No saved matches for this browser yet.</p>');llmDialog.innerHTML+=result.recovery?'<p>Server archive access enabled.</p>':'<details><summary>Recover older logs or use another browser</summary><p>Run <code>npm run logs:key</code> on the server with the same SGS_DATA_DIR, then enter the recovery key here. Keep this key private: it unlocks all game and AI archives.</p><form id="archive-recovery"><input name="key" type="password" autocomplete="off" required pattern="[a-f0-9]{64}" placeholder="Archive recovery key" aria-label="Archive recovery key"><button>Unlock archives</button></form></details>';if(!llmDialog.open)llmDialog.showModal();}
llmDialog.addEventListener('submit',async e=>{if(e.target.id!=='archive-recovery')return;e.preventDefault();const key=new FormData(e.target).get('key');const old=archiveKey;try{archiveKey=key;const result=await api('match-logs',{});if(!result.recovery)throw Error('Incorrect archive recovery key.');localStorage.setItem('sgs-archive-key',key);await showMatchLogs();}catch(err){archiveKey=old;toast(err.message);}});
llmDialog.addEventListener('click',async e=>{const test=e.target.closest('[data-test-ai]');if(test){const result=llmDialog.querySelector('.ai-connection-result');const buttons=[...llmDialog.querySelectorAll('[data-test-ai]:not(:disabled)')];buttons.forEach(b=>b.disabled=true);result.textContent='Testing '+test.textContent.replace('Test ','')+'…';try{const r=await api('llm-check',{model:test.dataset.testAi});result.textContent=(r.ok?'Connected':'Failed · '+r.status)+' · '+r.model+' · '+r.latencyMs+' ms · '+r.inputTokens+' input / '+r.outputTokens+' output tokens';}catch(err){result.textContent=err.message;}finally{buttons.forEach(b=>b.disabled=false);}return;}const id=e.target.closest('[data-download-match]')?.dataset.downloadMatch;if(!id)return;try{const res=await fetch('/api/match-log',{method:'POST',headers:{'Content-Type':'application/json','X-SGS-Archive-Key':archiveKey,Authorization:'Bearer '+token},body:JSON.stringify({matchId:id})});if(!res.ok){const data=await res.json();throw Error(data.error||'Download failed');}const url=URL.createObjectURL(await res.blob()),a=document.createElement('a');a.href=url;a.download='match-'+id+'.jsonl';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(err){toast(err.message);}});

llmDialog.addEventListener('click',async e=>{const test=e.target.closest('[data-test-ai]');if(test){const result=llmDialog.querySelector('.ai-connection-result');const buttons=[...llmDialog.querySelectorAll('[data-test-ai]:not(:disabled)')];buttons.forEach(b=>b.disabled=true);result.textContent='Testing '+test.textContent.replace('Test ','')+'…';try{const r=await api('llm-check',{model:test.dataset.testAi});result.textContent=(r.ok?'Connected':'Failed · '+r.status)+' · '+r.model+' · '+r.latencyMs+' ms · '+r.inputTokens+' input / '+r.outputTokens+' output tokens';}catch(err){result.textContent=err.message;}finally{buttons.forEach(b=>b.disabled=false);}return;}const id=e.target.closest('[data-review-match]')?.dataset.reviewMatch;if(!id)return;try{llmDialog.close();await openMatchReview(id);}catch(err){toast(err.message);}});

